"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[54408],{60610(a,n,i){i.r(n),i.d(n,{assets:()=>k,contentTitle:()=>r,default:()=>d,frontMatter:()=>u,metadata:()=>e,toc:()=>m});const e=JSON.parse('{"id":"learning/courses/practical-near-term-qc/introduction","title":"Introduction","description":"Pengantar kursus tentang aplikasi praktis komputasi kuantum.","source":"@site/i18n/id/docusaurus-plugin-content-docs/current/learning/courses/practical-near-term-qc/introduction.mdx","sourceDirName":"learning/courses/practical-near-term-qc","slug":"/learning/courses/practical-near-term-qc/introduction","permalink":"/learning/courses/practical-near-term-qc/introduction","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/learning/courses/practical-near-term-qc/introduction.mdx","tags":[],"version":"current","frontMatter":{"description":"Pengantar kursus tentang aplikasi praktis komputasi kuantum.","notebook_path":"learning/courses/practical-near-term-qc/introduction.ipynb","sidebar_label":"Introduction","title":"Introduction"},"sidebar":"tutorialsSidebar","previous":{"title":"Komputasi kuantum praktis jangka dekat","permalink":"/learning/courses/practical-near-term-qc/"},"next":{"title":"Ikhtisar","permalink":"/learning/courses/quantum-business-foundations/"}}');var t=i(74848),s=i(28453);const u={description:"Pengantar kursus tentang aplikasi praktis komputasi kuantum.",notebook_path:"learning/courses/practical-near-term-qc/introduction.ipynb",sidebar_label:"Introduction",title:"Introduction"},r="Pengantar komputasi kuantum praktis jangka dekat {#introduction-to-practical-near-term-quantum-computing}",k={},m=[{value:"Untuk apa komputer kuantum mungkin berguna",id:"what-quantum-computers-might-be-useful-for",level:2},{value:"Utilitas dan keunggulan kuantum jangka dekat",id:"near-term-quantum-utility-and-advantage",level:2},{value:"Dasar singkat teori kompleksitas",id:"a-brief-foundation-in-complexity-theory",level:2},{value:"Dari teori kompleksitas ke bukti praktis",id:"from-complexity-theory-to-practical-evidence",level:2},{value:"Bidang aplikasi dan studi kasus kursus",id:"application-areas-and-course-case-studies",level:2},{value:"Simulasi Hamiltonian",id:"hamiltonian-simulation",level:3},{value:"Optimisasi",id:"optimization",level:3},{value:"Machine learning kuantum",id:"quantum-machine-learning",level:3},{value:"Persamaan diferensial parsial",id:"partial-differential-equations",level:3},{value:"Kesimpulan",id:"conclusion",level:2}];function l(a){const n={h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",p:"p",strong:"strong",ul:"ul",...(0,s.R)(),...a.components};return(0,t.jsxs)(t.Fragment,{children:["\n",(0,t.jsx)(n.header,{children:(0,t.jsx)(n.h1,{id:"introduction-to-practical-near-term-quantum-computing",children:"Pengantar komputasi kuantum praktis jangka dekat"})}),"\n",(0,t.jsx)(n.p,{children:"Sejak komputer kuantum pertama kali diusulkan lebih dari empat dekade lalu, pertanyaannya selalu sama: seberapa jauh pendekatan baru ini bisa memperluas batas komputasi? Ilmu komputer teoretis memberi kita beberapa jawaban yang menarik. Komputer kuantum bisa memfaktorkan bilangan bulat besar jauh lebih cepat daripada metode klasik terbaik yang kita kenal, mempercepat pencarian tak terstruktur, dan mensimulasikan sistem kuantum dengan cara yang lebih alami. Tapi banyak dari ide-ide ini mengandaikan adanya komputer kuantum skala besar yang toleran terhadap kesalahan di masa depan."}),"\n",(0,t.jsx)(n.p,{children:"Teknologinya belum mencapai semua tujuan teoretis itu, tapi terus berkembang pesat. Para peneliti sekarang bisa memakai prosesor kuantum untuk menjelajahi masalah sains dan industri yang nyata. Di kursus ini, kamu akan langsung praktik dengan beberapa aplikasi yang paling menjanjikan. Kita akan memperkirakan properti energi rendah dari model molekul yang kompleks, mensimulasikan dinamika teori gauge kisi, dan menjelajahi bagaimana masalah portofolio keuangan bisa dipetakan ke komputer kuantum. Kita juga akan melihat bidang-bidang yang lebih baru, yang kemampuan komputer kuantumnya baru mulai kita pahami, termasuk machine learning kuantum (QML) dan pendekatan kuantum untuk persamaan diferensial parsial (PDE)."}),"\n",(0,t.jsx)(n.p,{children:"Banyak contoh di kursus ini cukup kecil untuk diselesaikan komputer klasik. Itu disengaja. Tujuannya adalah memberimu pengalaman nyata dengan seluruh proses memakai komputer kuantum untuk menyelesaikan masalah dunia nyata. Beberapa contoh mewakili masalah yang keunggulan kuantumnya mungkin muncul pada skala yang jauh lebih besar. Pada contoh lain, kita memakai metode yang disederhanakan supaya detail implementasi tidak menutupi ide kuantum utamanya."}),"\n",(0,t.jsx)(n.p,{children:"Di akhir kursus, kamu seharusnya punya gambaran umum tentang aplikasi kuantum utama dan intuisi tentang mengapa komputer kuantum mungkin berguna di bidang tertentu. Kamu akan bertemu dengan teknik-teknik umum untuk merepresentasikan masalah di komputer kuantum, belajar bagaimana metode kuantum dan klasik bekerja bersama, dan mulai mengenali alat dan tradeoff mana yang penting untuk berbagai jenis masalah."}),"\n",(0,t.jsx)(n.p,{children:"Di pelajaran pertama ini, kita akan membahas beberapa konsep dan istilah dasar yang membantumu memahami aplikasi komputasi kuantum secara garis besar, dan memberimu gambaran umum tentang bidang-bidang aplikasi utama yang aktif dikejar komunitas ilmiah."}),"\n",(0,t.jsx)(n.h2,{id:"what-quantum-computers-might-be-useful-for",children:"Untuk apa komputer kuantum mungkin berguna"}),"\n",(0,t.jsx)(n.p,{children:"Komputer kuantum sering digambarkan sebagai pesaing komputer klasik, tapi cara berpikir yang lebih tepat adalah menganggapnya sebagai sumber daya khusus dalam alur kerja klasik yang lebih besar. Jadi pertanyaan pentingnya: bagian komputasi mana yang sangat cocok untuk perangkat keras kuantum? Jawaban yang paling intuitif datang dari masalah yang memang sudah bersifat kuantum, seperti perilaku molekul, material, dan medan kuantum. Prosesor kuantum bisa merepresentasikan dan memanipulasi keadaan kuantum secara langsung, sedangkan sumber daya yang dibutuhkan untuk deskripsi klasik umum tumbuh secara eksponensial terhadap ukuran sistem."}),"\n",(0,t.jsx)(n.p,{children:"Kasusnya lebih rumit untuk masalah dengan input dan output klasik, tapi tetap ada alasan bagus untuk menjelajahinya. Masalah optimisasi sangat luas dan penting secara ekonomi, jadi peningkatan kecil sekalipun pada kualitas solusi atau waktu jalan bisa bernilai. Algoritma kuantum juga mungkin menawarkan cara baru untuk menjelajahi ruang solusi yang rumit atau memanfaatkan struktur pada kelas masalah tertentu. Machine learning kuantum punya motivasi teoretis yang kuat untuk masalah tertentu dengan input klasik, termasuk klasifikasi terstruktur dan pemrosesan dataset yang sangat besar. Namun, apakah hasil ini bisa berubah menjadi keunggulan praktis pada data klasik dunia nyata masih menjadi pertanyaan terbuka. Persamaan diferensial parsial menggambarkan banyak sistem penting di sains, rekayasa, dan keuangan, dan algoritma kuantum mungkin memperbaiki penskalaan untuk simulasi berdimensi tinggi tertentu dan masalah aljabar linear berukuran besar."}),"\n",(0,t.jsx)(n.p,{children:"Namun di ketiga bidang ini, biaya untuk menyiapkan input klasik, menjalankan komputasi kuantum, dan mengekstrak jawaban klasik yang berguna bisa lebih besar daripada manfaat langkah kuantumnya. Kita akan terus mengingat tantangan praktis ini sambil menjelajahi bagaimana metode kuantum diterapkan di tiap bidang."}),"\n",(0,t.jsx)(n.h2,{id:"near-term-quantum-utility-and-advantage",children:"Utilitas dan keunggulan kuantum jangka dekat"}),"\n",(0,t.jsx)(n.p,{children:"Kursus ini tidak secara khusus tentang keunggulan kuantum, tapi pembahasan tentang keunggulan kuantum tidak bisa dihindari. Motivasi mendasar di balik aplikasi kuantum adalah memakai sumber daya kuantum untuk memperluas apa yang bisa dilakukan komputer klasik sendirian: menghasilkan hasil yang lebih akurat, mencapai solusi lebih cepat, atau menyelesaikan masalah yang sebelumnya tidak terjangkau. Istilah-istilah terkait berikut membantu kita membicarakan kemajuan yang kita lihat dengan jelas:"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Quantum speedup (percepatan kuantum):"})," Seiring ukuran masalah bertambah, waktu yang dibutuhkan metode kuantum tumbuh lebih lambat dibanding metode klasik terbaik yang relevan untuk tugas yang sama."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Quantum advantage (keunggulan kuantum):"})," Komputasi berbasis kuantum mengungguli pendekatan klasik terbaik yang relevan pada tugas yang terdefinisi dengan baik dan metrik yang bermakna. Alih-alih satu tonggak yang permanen, keunggulan kuantum adalah batas yang terus berkembang dan bergeser seiring membaiknya metode kuantum maupun klasik."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Quantum utility (utilitas kuantum):"})," Komputasi kuantum yang berkontribusi pada hasil ilmiah atau teknis yang berguna. Komputasi ini berjalan pada skala, kedalaman, dan akurasi di luar jangkauan simulasi klasik brute-force yang praktis, tanpa harus mengungguli metode klasik terbaik."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Algoritma jangka dekat:"})," Algoritma yang dirancang untuk prosesor kuantum saat ini, memakai kedalaman circuit terbatas dan sering mengandalkan pasca-pemrosesan klasik dan mitigasi kesalahan, bukan koreksi kesalahan kuantum penuh."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Komputasi kuantum toleran kesalahan:"})," Di masa depan, komputasi kuantum akan memakai koreksi kesalahan kuantum untuk melindungi qubit logis sepanjang komputasi. Ketika laju kesalahan fisik berada di bawah ambang toleransi kesalahan, sumber daya koreksi kesalahan tambahan bisa menekan kesalahan logis sampai tingkat yang dibutuhkan komputasi panjang yang andal. Toleransi kesalahan memungkinkan algoritma yang jauh lebih dalam, termasuk implementasi skala besar algoritma Shor."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Toleransi kesalahan awal:"})," Toleransi kesalahan berarti kesalahan ditekan, bukan dihilangkan sepenuhnya. Pada sistem toleran kesalahan awal, sisa kesalahan logis tetap harus diperhitungkan, dan kedalaman circuit yang andal masih terbatas."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Algoritma heuristik:"})," Metode yang dirancang untuk menemukan solusi yang baik dalam praktik tanpa menjamin jawaban optimal atau waktu jalan tertentu."]}),"\n"]}),"\n"]}),"\n",(0,t.jsx)(n.h2,{id:"a-brief-foundation-in-complexity-theory",children:"Dasar singkat teori kompleksitas"}),"\n",(0,t.jsx)(n.p,{children:"Di beberapa bidang aplikasi, kita punya alasan teoretis yang kuat untuk mengharapkan bahwa komputer kuantum mungkin punya keunggulan. Untuk memahami dari mana keyakinan itu datang, kita butuh sedikit kosakata dari teori kompleksitas."}),"\n",(0,t.jsx)(n.p,{children:"Teori kompleksitas mempelajari bagaimana sumber daya yang dibutuhkan untuk menyelesaikan masalah tumbuh seiring masalahnya membesar. Teori ini memberi kita peta yang berguna tentang di mana percepatan kuantum mungkin terjadi. Beberapa istilah sangat penting untuk kursus ini:"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"P:"})," Masalah yang bisa diselesaikan komputer klasik secara efisien, artinya sumber daya yang dibutuhkan tumbuh secara polinomial terhadap ukuran masalah."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"NP:"})," Masalah yang solusi usulannya bisa kamu periksa secara efisien, meskipun menemukan solusinya mungkin sangat sulit."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"NP-hard:"})," Masalah yang setidaknya sesulit setiap masalah di NP. Masalah NP-hard tidak harus termasuk NP. Banyak masalah optimisasi bersifat NP-hard."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"NP-complete:"})," Masalah yang sekaligus NP-hard dan berada di NP. Ini adalah masalah keputusan tersulit di dalam NP."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"BQP:"})," Masalah yang bisa diselesaikan komputer kuantum secara efisien dengan probabilitas kesalahan yang terbatas."]}),"\n"]}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:"Beberapa hubungan di antara kategori-kategori ini sudah diketahui. P termasuk di dalam NP dan BQP karena masalah yang bisa diselesaikan secara efisien di komputer klasik juga bisa diperiksa secara klasik dan diselesaikan di komputer kuantum. Hubungan lainnya masih terbuka. Kita tidak tahu apakah P sama dengan NP atau apakah NP termasuk di dalam BQP. Meski begitu, para peneliti umumnya percaya bahwa P lebih kecil daripada NP maupun BQP, dan bahwa komputer kuantum tidak bisa menyelesaikan setiap masalah NP-complete secara efisien. Singkatnya, komputer kuantum bukan kotak ajaib yang langsung menyelesaikan semua masalah sulit."}),"\n",(0,t.jsx)(n.p,{children:"Argumen berbasis kompleksitas yang paling kuat untuk komputasi kuantum berlaku pada jenis masalah tertentu. Algoritma Shor berskala jauh lebih baik daripada algoritma klasik terbaik yang kita kenal untuk pemfaktoran dan logaritma diskret, meskipun belum terbukti bahwa pemfaktoran berada di luar P. Simulasi kuantum umum juga punya landasan teoretis yang kuat. Beberapa masalah simulasi kuantum bersifat BQP-complete, artinya menyelesaikannya secara klasik dengan efisien sama saja dengan mensimulasikan komputasi kuantum apa pun secara efisien. Simulasi klasik yang efisien seperti itu sangat tidak masuk akal, dan ini salah satu alasan simulasi Hamiltonian kuantum dianggap sebagai bidang aplikasi yang begitu menjanjikan."}),"\n",(0,t.jsx)(n.p,{children:"Beberapa PDE berdimensi tinggi bisa direduksi menjadi masalah sistem linear yang BQP-complete, sehingga kita punya alasan kuat untuk mengharapkan percepatan kuantum ketika input dan output bisa ditangani secara efisien. QML punya contoh serupa: beberapa tugas yang melibatkan data kuantum bersifat BQP-complete, dan beberapa model kuantum bisa menghasilkan sampel yang sulit direproduksi secara klasik."}),"\n",(0,t.jsx)(n.p,{children:"Kasus optimisasi kurang lugas. Komputer kuantum tidak diharapkan bisa menyelesaikan masalah NP-hard sembarang secara efisien, tapi mereka masih mungkin membantu pada masalah terstruktur, instans tertentu, atau langkah spesifik dalam alur kerja optimisasi. Algoritma Grover, misalnya, memberikan percepatan kuadratik untuk pencarian tak terstruktur. Itu peningkatan yang berarti, meskipun akar kuadrat dari ruang pencarian yang sangat besar tetap bisa sangat besar."}),"\n",(0,t.jsx)(n.h2,{id:"from-complexity-theory-to-practical-evidence",children:"Dari teori kompleksitas ke bukti praktis"}),"\n",(0,t.jsx)(n.p,{children:"Teori kompleksitas bisa memberi tahu kita di mana percepatan kuantum mungkin terjadi, tapi biasanya tidak bisa memberi tahu bagaimana sebuah metode bekerja pada masalah tertentu atau komputer kuantum tertentu. Banyak metode yang dipakai di perangkat keras saat ini bersifat heuristik. Metode itu dirancang untuk menemukan jawaban yang baik dalam praktik, tapi tidak menjamin jawaban terbaik atau waktu jalan tertentu."}),"\n",(0,t.jsx)(n.p,{children:"Heuristik bukan hal khas komputasi kuantum, dan menyebut sebuah metode heuristik tidak berarti metode itu tidak andal atau tidak ilmiah. Optimisasi klasik, machine learning, dan kimia komputasi semuanya sangat bergantung pada heuristik ketika solusi eksak terlalu mahal. Heuristik kuantum mungkin menawarkan cara baru untuk menjelajahi ruang solusi, menyiapkan keadaan yang berguna, atau mengidentifikasi kandidat yang menjanjikan. Apakah ia bekerja dengan baik adalah pertanyaan empiris: kita harus menjalankannya dan mengukur hasilnya."}),"\n",(0,t.jsx)(n.p,{children:"Karena heuristik tidak disertai jaminan kinerja, kita mengevaluasinya dengan metrik keberhasilan yang jelas, baseline klasik yang kuat, dan pengujian pada berbagai ukuran masalah. Ini membantu kita melihat di mana sebuah metode bekerja dengan baik dan bagaimana kinerjanya berubah saat masalah membesar."}),"\n",(0,t.jsx)(n.h2,{id:"application-areas-and-course-case-studies",children:"Bidang aplikasi dan studi kasus kursus"}),"\n",(0,t.jsx)(n.p,{children:"Kita menyusun kursus ini di sekitar empat bidang aplikasi yang luas. Bidang-bidang ini tidak mencakup setiap kemungkinan pemakaian komputer kuantum, tapi memberi kita cara yang berguna untuk membandingkan di mana argumen terkuat berada dan di mana pertanyaan terbukanya."}),"\n",(0,t.jsx)(n.h3,{id:"hamiltonian-simulation",children:"Simulasi Hamiltonian"}),"\n",(0,t.jsx)(n.p,{children:"Simulasi Hamiltonian mencakup memperkirakan energi, mempelajari properti kimia dan material, dan memodelkan bagaimana sistem kuantum berubah terhadap waktu. Bidang ini menjangkau kimia, ilmu material, fisika materi terkondensasi, serta fisika energi tinggi dan nuklir. Studi kasus kita menelaah model besi-belerang yang berkorelasi kuat memakai sample-based quantum diagonalization dan mensimulasikan dinamika hadron memakai representasi kisi yang peka simetri. Ini dua contoh dari bidang yang jauh lebih luas, yang juga mencakup mekanisme reaksi, material magnetik, dan dinamika banyak-benda lainnya."}),"\n",(0,t.jsx)(n.h3,{id:"optimization",children:"Optimisasi"}),"\n",(0,t.jsx)(n.p,{children:"Optimisasi muncul di mana-mana, dari keuangan dan logistik sampai penjadwalan dan sistem energi. Ini juga bidang yang keunggulannya sulit dibuktikan, karena solver klasik sangat mumpuni dan pemetaan kuantum bisa menambah overhead yang mahal. Studi kasus kita memakai pemilihan portofolio untuk menjelajahi bagaimana masalah optimisasi direpresentasikan, dijalankan, dan di-benchmark tanpa mengasumsikan bahwa komputer kuantum otomatis menemukan optimum yang eksak."}),"\n",(0,t.jsx)(n.h3,{id:"quantum-machine-learning",children:"Machine learning kuantum"}),"\n",(0,t.jsx)(n.p,{children:"Machine learning kuantum menanyakan apakah circuit kuantum atau data kuantum bisa meningkatkan tugas pembelajaran. Pertanyaan pentingnya meliputi pengodean data, biaya pelatihan, generalisasi, dan perbandingan dengan model klasik yang kuat."}),"\n",(0,t.jsx)(n.h3,{id:"partial-differential-equations",children:"Persamaan diferensial parsial"}),"\n",(0,t.jsx)(n.p,{children:"Persamaan diferensial parsial menggambarkan sistem seperti fluida, panas, dan gelombang. Algoritma kuantum mungkin mempercepat bagian dari beberapa alur kerja PDE, tapi persiapan data dan ekstraksi jawaban klasik yang berguna bisa menjadi biaya besar. Studi kasus spesifiknya masih dikembangkan."}),"\n",(0,t.jsx)(n.p,{children:"Di pelajaran-pelajaran berikutnya, kita akan menanyakan pertanyaan dasar yang sama di tiap bidang: Apa masalahnya, mengapa komputasi kuantum mungkin membantu, apa keterbatasannya, dan apa yang sebenarnya ditunjukkan oleh bukti? Kita akan mulai dengan simulasi Hamiltonian, di mana masalahnya sendiri bersifat kuantum."}),"\n",(0,t.jsx)(n.h2,{id:"conclusion",children:"Kesimpulan"}),"\n",(0,t.jsx)(n.p,{children:"Kita sudah membahas banyak hal, tapi ide utamanya sederhana: komputer kuantum adalah alat khusus, dan nilainya bergantung pada pemakaian metode kuantum yang tepat untuk masalah yang tepat atau bagian dari masalah yang lebih besar. Simulasi Hamiltonian punya landasan teoretis yang paling jelas, optimisasi punya seperangkat metode heuristik dan benchmark yang matang, dan QML serta PDE menawarkan arah yang menjanjikan yang masih berkembang."}),"\n",(0,t.jsx)(n.p,{children:"Di pelajaran-pelajaran berikutnya, kita akan beralih dari gambaran umum ini ke contoh praktik langsung. Untuk setiap aplikasi, kita akan menanyakan masalah apa yang ingin kita selesaikan, peran apa yang dimainkan komputer kuantum, bagaimana hasilnya ditafsirkan, dan apa yang bisa kita pelajari darinya. Tujuannya adalah membangun intuisimu tentang di mana komputasi kuantum mungkin membantu dan apa yang dibutuhkan untuk mengubah ide yang menjanjikan menjadi komputasi nyata."}),"\n"]})}function d(a={}){const{wrapper:n}={...(0,s.R)(),...a.components};return n?(0,t.jsx)(n,{...a,children:(0,t.jsx)(l,{...a})}):l(a)}},28453(a,n,i){i.d(n,{R:()=>u,x:()=>r});var e=i(96540);const t={},s=e.createContext(t);function u(a){const n=e.useContext(s);return e.useMemo(function(){return"function"==typeof a?a(n):{...n,...a}},[n,a])}function r(a){let n;return n=a.disableParentContext?"function"==typeof a.components?a.components(t):a.components||t:u(a.components),e.createElement(s.Provider,{value:n},a.children)}}}]);